{"hypotheses": [
  {
    "name": "Volatility Catcher",
    "mechanism": "Companies with high asset growth, but low short-term reversal are likely to experience high volatility. This strategy benefits from this volatility through price fluctuations.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": -0.5, "primitive": "STreversal"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "above", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Capital Efficiency",
    "mechanism": "Firms with high operating profits and low debt are likely to perform better as they are more efficient in their capital allocation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": -1.0, "primitive": "DebtIssuance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Growth Momentum",
    "mechanism": "Companies with high asset growth and high earnings forecast are likely to have strong positive momentum, leading to an upward pressure on the stock price.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "EarningsForecastDisparity"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Quality Value",
    "mechanism": "High book-to-market firms with high operating profitability tend to be undervalued quality companies, which should earn excess returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 1.0, "primitive": "OperProf"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "above", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Innovation Potential",
    "mechanism": "Companies with high R&D spending and low asset growth are likely to have a high innovation potential which could lead to excess future returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": -1.0, "primitive": "AssetGrowth"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Leverage Reversal",
    "mechanism": "Companies with high leverage but low short-term reversal are likely to experience a turnaround, due to the possibility of restructuring or improved operating performance.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Leverage"},
        {"weight": -0.5, "primitive": "STreversal"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Growth Uncertainty",
    "mechanism": "Companies with high asset growth and high earnings forecast disparity could have higher uncertainty leading to higher risk premiums.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "EarningsForecastDisparity"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Quality Growth",
    "mechanism": "High gross profitability firms with high asset growth are likely to be high-quality growth companies, which should earn excess returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GP"},
        {"weight": 0.5, "primitive": "AssetGrowth"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "GP", "bound": "above", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  }
]}
